LIB_AXIS, LIB_SPREAD, LIB_SETTLE = LIB_TABLE[:, 0:3], LIB_TABLE[:, 3], LIB_TABLE[:, 4]
LIB_SCEN_AXIS = LIB_TABLE[:, 5:17].reshape(-1, 4, 3)

# Plant variants the check knows: the nominal one, then the four of the LIB_TABLE columns, in that order.
VARIANTS = ("nominal_v0", "weak_v1", "heavy_v1", "slippery_v1", "light_v1")

_state = {"plan": None, "predictors": None, "predictor_failed": False, "alive": [], "target": None, "a_open": None}


def plan_actions(row, a_open):
    """Expand a library row into the (N_STEPS, 24) action sequence."""
    durs = row[:3].astype(int)
    keys = row[3:].reshape(3, 24) / 100.0
    acts = np.empty((N_STEPS, 24))
    prev, t = a_open, 0
    for k in range(3):
        n = int(durs[k])
        for j in range(n):
            if t >= N_STEPS:
                break
            acts[t] = prev + (keys[k] - prev) * ((j + 1) / n)
            t += 1
        prev = keys[k]
    acts[t:] = prev
    return acts


def rank_plans(target):
    """Library indices, best first. Plans whose table outcome is inside the cone come first, ordered
    by robustness, speed and centring; the rest follow by angular distance."""
    angle = np.degrees(np.arccos(np.clip(LIB_AXIS @ target, -1.0, 1.0))) + LIB_SPREAD
    still_good = (LIB_SCEN_AXIS @ target) > np.cos(np.radians(PARAMS["scen_cone"]))
    weights = np.array([PARAMS["w_robust"], PARAMS["w_robust"], PARAMS["w_slip"], PARAMS["w_robust"]])
    score = still_good @ weights + PARAMS["w_fast"] * LIB_SETTLE - angle
    score = np.where(angle < PARAMS["table_cone"], score, -1000.0 - angle)
    return np.argsort(-score)


class Predictor:
    """A private copy of the plant, reset exactly as the benchmark resets it."""

    def __init__(self, variant="nominal_v0"):
        import mujoco
        from hl_control.envs.adroit import AdroitConfig, AdroitEnv
        from gymnasium_robotics.utils.rotations import euler2quat
        self._mj, self._euler2quat = mujoco, euler2quat
        self.sim = AdroitEnv(AdroitConfig(task="pen", scenario=variant)).sim

    def start(self, target):
        """Put the pen and the target where an episode starts."""
        sim, mj = self.sim, self._mj
        roll, pitch = np.arctan2(-target[1], target[2]), np.arcsin(np.clip(target[0], -1.0, 1.0))
        mj.mj_resetData(sim.model, sim.data)
        sim.model.body_quat[sim.target_obj_body_id] = self._euler2quat(np.array([roll, pitch, 0.0]))
        sim.set_state(sim.init_qpos, sim.init_qvel)

    def step(self, action):
        """Apply one action; return the predicted joints and pen state (observation channels 0-35)."""
        sim = self.sim
        sim.do_simulation(sim.act_mean + np.clip(action, -1.0, 1.0) * sim.act_rng, sim.frame_skip)
        return np.asarray(sim._get_obs(), dtype=float)[:36]

    def rollout(self, target, actions):
        """Score an action sequence for a target axis: (final run of success steps, smallest cosine
        and largest centre distance over the last HOLD steps)."""
        self.start(target)
        sim = self.sim
        d = sim.data
        ctrl = sim.act_mean + np.clip(actions, -1.0, 1.0) * sim.act_rng
        cos = np.zeros(N_STEPS)
        dist = np.zeros(N_STEPS)
        for i in range(N_STEPS):
            sim.do_simulation(ctrl[i], sim.frame_skip)
            pen = d.site_xpos[sim.obj_t_site_id] - d.site_xpos[sim.obj_b_site_id]
            tar = d.site_xpos[sim.tar_t_site_id] - d.site_xpos[sim.tar_b_site_id]
            cos[i] = pen @ tar / (np.linalg.norm(pen) * np.linalg.norm(tar))
            dist[i] = np.linalg.norm(d.xpos[sim.obj_body_id] - d.site_xpos[sim.eps_ball_site_id])
            if d.xpos[sim.obj_body_id][2] < DIST_OK:      # dropped: this plan is out
                return 0, -1.0, 1.0
        ok = (cos > COS_OK) & (dist < DIST_OK)
        held = 0
        for flag in ok[::-1]:
            if not flag:
                break
            held += 1
        return held, float(cos[-HOLD:].min()), float(dist[-HOLD:].max())


def verify(predictor, target, candidates):
    """Roll candidate action sequences out on a predictor, in order; return the first that passes
    the hold condition with the margins, else the best-scoring one (None if nothing could be run)."""
    best, best_score = None, None
    for actions in candidates:
        try:
            held, cmin, dmax = predictor.rollout(target, actions)
        except Exception:
            break
        score = (min(held, HOLD), cmin - 4.0 * max(0.0, dmax - 0.06))
        if best_score is None or score > best_score:
            best, best_score = actions, score
        if held >= HOLD and cmin > COS_OK + PARAMS["cos_margin"] and dmax < DIST_OK - PARAMS["dist_margin"]:
            break
    return best


def choose_plan(obs):
    """Step 0: pick the plan for this episode's target on the nominal plant and arm the plant check."""
    o = np.asarray(obs["observation"], dtype=float)
    target = o[36:39] / max(np.linalg.norm(o[36:39]), 1e-9)
    a_open = np.clip((0.0 - np.asarray(obs["ctrl_mean"])) / np.asarray(obs["ctrl_half_range"]), -1.0, 1.0)
    _state["target"], _state["a_open"], _state["alive"] = target, a_open, []
    if _state["predictors"] is None and not _state["predictor_failed"]:
        try:
            _state["predictors"] = [Predictor(v) for v in VARIANTS]
        except Exception:                                  # no simulator: trust the table
            _state["predictor_failed"] = True
    order = rank_plans(target)[: int(PARAMS["n_verify"])]
    plan = plan_actions(LIBRARY[order[0]], a_open)
    predictors = _state["predictors"]
    if predictors is None:
        return plan
    best = verify(predictors[0], target, (plan_actions(LIBRARY[i], a_open) for i in order))
    try:
        for p in predictors:
            p.start(target)
        _state["alive"] = list(range(len(VARIANTS)))
    except Exception:
        _state["alive"] = []
    return plan if best is None else best


def check_plant(obs, step):
    """Steps 1..track_steps: advance the surviving predictors by the action just applied, drop those
    that no longer reproduce the measurement, and re-plan once a single non-nominal variant is left."""
    predictors, plan = _state["predictors"], _state["plan"]
    measured = np.asarray(obs["observation"], dtype=float)[:36]
    alive = []
    for v in _state["alive"]:
        if np.max(np.abs(predictors[v].step(plan[step - 1]) - measured)) < PARAMS["match_tol"]:
            alive.append(v)
    if alive == [0] or step >= PARAMS["track_steps"]:     # nominal plant (or undecided for too long): done
        alive = []
    _state["alive"] = alive
    if len(alive) != 1:
        return
    v, target = alive[0], _state["target"]                 # the plant is variant v: re-plan steps step..end
    _state["alive"] = []
    cos = LIB_SCEN_AXIS[:, v - 1] @ target                 # tabulated outcome of every plan on that variant
    order = [i for i in np.argsort(-cos)[: int(PARAMS["n_replan"])] if cos[i] > PARAMS["replan_cos"]]
    candidates = [plan] + [np.vstack([plan[:step], plan_actions(LIBRARY[i], _state["a_open"])[step:]]) for i in order]
    best = verify(predictors[v], target, candidates)
    if best is not None:
        _state["plan"] = best


def controller(obs: dict) -> np.ndarray:
    step = int(obs["step"])
    if step == 0 or _state["plan"] is None:
        _state["plan"] = choose_plan(obs)
    elif _state["alive"]:
        try:
            check_plant(obs, step)
        except Exception:
            _state["alive"] = []
    return _state["plan"][min(step, N_STEPS - 1)].copy()
